<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { ElConfigProvider } from 'element-plus';
import zhCn from 'element-plus/es/locale/lang/zh-cn';
import 'element-plus/dist/index.css';
import { account, signOut } from './session.ts';
import { h5Path } from './visitor.ts';
import { message } from '../../shared/contracts.ts';

const route=useRoute(), router=useRouter();
const menu=ref(false), error=ref('');
const nav=[{section:'工作空间',links:[{to:'/',label:'内容工作台',symbol:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',capability:''}]},
  {section:'产品管理',links:[{to:'/products',label:'全部产品',symbol:'M9 2h6v3H9z M10 5v3l-3 3v9q0 2 2 2h6q2 0 2-2v-9l-3-3V5 M7 13h10 M7 18h10',capability:'edit'}]},
  {section:'品牌案例',links:[{to:'/cases',label:'全部案例',symbol:'M3 7h18v13H3z M8 7V4h8v3 M3 12q9 4 18 0 M10 13h4',capability:'edit'}]},
  {section:'展示内容',links:[{to:'/pages/home_posters',label:'首页海报',symbol:'M3 4h18v16H3z M4 16l5-5 4 4 3-3 4 4 M16 8h.1',capability:'edit'},{to:'/pages/catalog_cover',label:'目录封面',symbol:'M3 5h18v14H3z M6 10h12 M6 14h8',capability:'edit'},{to:'/directory',label:'板块与分类',symbol:'M3 4h7v6H3z M14 14h7v6h-7z M6 10v7h8',capability:'edit'},{to:'/pages/services',label:'服务卡片',symbol:'M4 6h16 M4 12h16 M4 18h10',capability:'edit'},{to:'/pages/business_contact',label:'商务联系',symbol:'M4 5h16v13H9l-5 3z M8 9h8 M8 13h5',capability:'edit'}]},
  {section:'发布与治理',links:[{to:'/release',label:'发布检查',symbol:'M12 3v12 M8 7l4-4 4 4 M4 14v6h16v-6',capability:'publish'},{to:'/history',label:'版本与下架',symbol:'M3 11a9 9 0 1 1 2 7 M3 5v6h6 M12 7v6l4 2',capability:'edit'},{to:'/accounts',label:'账号与操作记录',symbol:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21q0-7 7-7t7 7 M15 5q6 1 3 6 M18 15q3 1 4 5',capability:'audit'}]}];
const crumb=computed(()=>nav.flatMap(group=>group.links).find(link=>link.to==='/'?route.path==='/':route.path===link.to||route.path.startsWith(`${link.to}/`))?.label??'内容维护');
function visible(capability:string){return capability==='publish'?account.value?.can_publish:capability==='edit'?account.value?.can_edit:capability==='audit'?account.value?.can_edit||account.value?.can_manage:true;}
watch(account,(current)=>{if(!current && route.name!=='login') void router.replace({name:'login'}); if(current && route.meta.edit && !current.can_edit) void router.replace('/');});
watch(()=>route.path,()=>{menu.value=false;error.value='';});
async function exit(){try{await signOut();await router.replace('/login');}catch(cause){error.value=message(cause);}}
</script>

<template>
  <ElConfigProvider :locale="zhCn">
    <RouterView v-if="route.name==='login'" :key="route.path" />
    <div v-else-if="account && !account.must_change_password" class="layout" data-ui>
      <aside class="rail" :class="{'menu-open':menu}">
        <RouterLink class="brand" to="/"><svg class="brand-mark" aria-hidden="true" viewBox="0 0 36 42"><path d="M9 3h15v5H9zM12 9v9L4 31v6q0 3 4 3h17q4 0 4-3v-7l-9-12V9M9 28h16m-14 6h11M31 5v10m-4-5h8"/></svg><div><strong>企业产品图册</strong><small>企业内容工作空间</small></div></RouterLink>
        <div v-for="group in nav" :key="group.section" class="nav-group" :hidden="!group.links.some(link=>visible(link.capability))">
          <p class="group">{{ group.section }}</p>
          <RouterLink v-for="link in group.links.filter(link=>visible(link.capability))" :key="link.to" :to="link.to" :class="['nav-row',{'nav-current':link.to==='/'?route.path==='/':route.path===link.to||route.path.startsWith(`${link.to}/`)}]"><svg class="nav-glyph" viewBox="0 0 24 24" aria-hidden="true"><path :d="link.symbol"/></svg>{{ link.label }}</RouterLink>
        </div>
        <a class="rail-preview" :href="h5Path('/')" target="_blank" rel="noopener">打开公开 H5 ↗</a>
      </aside>
      <div class="workspace">
        <div class="topbar"><button class="btn mobile-menu" :aria-expanded="menu" @click="menu=!menu">{{ menu?'关闭导航':'菜单' }}</button><span class="crumb">企业产品图册　／　{{crumb}}</span><div class="topbar-right"><span>{{ account.login }}</span><span class="pill">{{ account.can_publish?'发布人员':account.can_edit?'内容编辑':account.can_manage?'账号管理员':'已登录' }}</span><button class="btn link" @click="exit">退出</button></div></div>
        <main class="sheet"><p v-if="error" role="alert" class="inline-error">{{ error }}</p><RouterView :key="route.path" /></main>
      </div>
    </div>
  </ElConfigProvider>
</template>

<style>
:root{--ink:#172d36;--blue:#255b71;--accent:#c4dde5;--muted:#51666e;--line:#dbe4e7;--frame:#f0f4f5;--soft:#f4f8f9;--ok:#246347;--warn:#805520;--radius:9px;--el-color-primary:#255b71;font:14px/1.55 'Microsoft YaHei UI','PingFang SC','Microsoft YaHei',system-ui,sans-serif;color:var(--ink);background:var(--frame);font-variant-numeric:tabular-nums}
